package main

import (
	"errors"
	"sync/atomic"
)

// The executable selects its language before rendering; package tests start in Spanish.
var uiLocale atomic.Uint32

func setUILanguage(code string) error {
	switch code {
	case "es":
		uiLocale.Store(0)
	case "en":
		uiLocale.Store(1)
	default:
		return errors.New("unsupported UI language: use en or es")
	}
	return nil
}

func uiLanguage() string {
	if uiLocale.Load() == 1 {
		return "en"
	}
	return "es"
}

// Call only with Fluke's own fixed literals, never user, model or repository text.
func uiText(s string) string {
	if uiLocale.Load() == 1 {
		if translated, ok := uiEnglish[s]; ok {
			return translated
		}
	}
	return s
}

