func (m *model) toggleUILanguage() {
	next := m.state
	next.Language = "en"
	message := "Interface language: English."
	if uiLanguage() == "en" {
		next.Language = "es"
		message = "Idioma de la interfaz: español."
	}
	if !m.saveEdit(next, message) {
		return
	}
	_ = setUILanguage(next.Language)
	m.review.lines = nil
}
